UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Neonatal Resuscitation (NRP)","body":"[Algorithm — Quick Reference](#/node/nrp-algorithm-ref)\n[Setup and Tools — Quick Reference](#/node/nrp-setup-ref)\n[NRP Steps Summary](#/info/nrp-summary) — quick-reference checklist for neonatal resuscitation.\n\n**Neonatal resuscitation** follows a systematic, stepwise approach from initial assessment through advanced interventions.\n\n**Key statistics:** [1]\n• ~90% of newborns transition without intervention beyond warmth, drying, and stimulation\n• ~10% need early support (PPV, supplemental O2)\n• <1% need extensive resuscitation (CPR + medications)\n\n**Modules:**\n• Module 1: Preparation & Initial Assessment — team, equipment, cord management, initial evaluation\n• Module 2: Initial Steps — Golden 30 Seconds (warm, dry, position, stimulate, clear)\n• Module 3: Positive Pressure Ventilation — PPV technique, corrective steps, advanced airway\n• Module 4: Chest Compressions — CPR technique, intubation\n• Module 5: Medications & Vascular Access — epinephrine, UVC, volume resuscitation\n• Module 6: Post-Resuscitation — APGAR, normothermia, NICU transfer\n\n**Cross-links:**\n• [Precipitous Delivery](#/tree/precip-delivery) — ED delivery management\n• [Shoulder Dystocia](#/tree/shoulder-dystocia) — if turtle sign during delivery\n\nFor the ED-specific context (precipitous delivery + neonatal resuscitation outside L&D), see McFarlin. [8]","citation":[1,2,8],"next":"nrp-preparation","calculatorLinks":[{"id":"neo-numbers","label":"Neonate Numbers (<3 kg)"}],"summary":"Stepwise NRP overview — 90% need no intervention, 10% need PPV/O2, <1% need CPR + meds; 6 modules from prep to post-resus","skippable":true}'::jsonb
WHERE id = 'nrp-start' AND tree_id = 'neonatal-resus';

-- Node: nrp-cord-mgmt (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Cord Management (2025 Update)","body":"DELAYED CORD CLAMPING (DCC) — 2025 GUIDELINES [1][5]\n\n**Vigorous term/late preterm:**\n• DCC **at least 60 seconds** recommended\n• Improves placental transfusion, iron stores, and hemoglobin\n\n**Non-vigorous ≥35 weeks:**\n• **Intact cord milking (ICM)** may be reasonable (compared to immediate clamping)\n• Milk cord toward baby 3–4 times over 2 seconds\n\n**Preterm 28–34 weeks:**\n• ICM when DCC isn''t possible\n\n**<28 weeks:**\n• ICM is **NOT recommended** — risk of intraventricular hemorrhage\n\n**Clamp immediately if:**\n• Baby needs resuscitation and can''t wait\n• Placental abruption, cord avulsion, or other emergency\n\n**Communicate cord management plan to the team before delivery.** [5]","citation":[1,5],"next":"nrp-preterm","summary":"DCC at least 60 sec for vigorous term; intact cord milking if non-vigorous ≥35wk; NO milking <28wk (IVH risk); clamp immediately if resus needed"}'::jsonb
WHERE id = 'nrp-cord-mgmt' AND tree_id = 'neonatal-resus';

-- Node: nrp-preterm (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Preterm Considerations","body":"PRETERM ASSESSMENT [1][2]\n\n**Viability assessment:**\n• Dating most accurate in 1st trimester (±3–5 days)\n• Later dating accuracy: ±1–2 weeks\n• U/S: BPD + femur length for estimation\n\n**Preterm-specific needs:**\n• **Plastic wrap <32 weeks** — cover body (not face) to prevent heat loss\n• **Starting FiO2 by gestational age** — 21% for ≥35 wk; 21–30% for 32 to <35 wk; 30–100% for <32 wk (titrate to SpO2 targets) [1]\n• **Temperature is critical** — hypothermia worsens all outcomes\n• **Surfactant** may be needed if <32 wk (NICU decision)\n\n**Gestational age estimation if unknown:**\n• Weight: ~500g at 23–24 wk, ~1000g at 28 wk, ~1500g at 32 wk, ~2500g at 37 wk\n• Sole creases, ear cartilage, breast tissue for Ballard score (post-resuscitation)\n\n**Both hypothermia AND hyperthermia worsen outcomes.** Target normothermia (36.5–37.5°C) for all infants. [1]","citation":[1,2],"next":"nrp-initial-eval","summary":"Plastic wrap <32wk, higher starting FiO2 for preterm, temperature is critical — both hypo/hyperthermia worsen outcomes","skippable":true}'::jsonb
WHERE id = 'nrp-preterm' AND tree_id = 'neonatal-resus';

-- Node: nrp-routine (1 field(s) changed)
