-- Node: nrp-ppv (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Positive Pressure Ventilation (PPV)","body":"PPV — The Most Important Intervention in NRP [1][2][3]\n\n**T-piece resuscitator preferred** (2025) — provides consistent PIP and PEEP. Self-inflating bag acceptable if T-piece unavailable. [1]\n\n**TECHNIQUE:**\n• **C-E grip** — C fingers seal mask, E fingers lift jaw\n• **Mask seal** — covers mouth and nose, not eyes\n• **Sniffing position** — slight neck extension\n• **PIP** initial 20–30 cmH2O, higher only if HR does not rise (avoid barotrauma) [1]\n• **Rate** 30–60/min (\"squeeze—release—release\") [1]\n• **FiO2** start at 21% for ≥35 weeks; 21–30% for 32 to <35 weeks; 30–100% for <32 weeks [1]\n• **Confirm chest rise** and bilateral breath sounds\n\n**SpO2 TARGETS by minute:** [1]\n• 1 min: 60–65% → 2 min: 65–70% → 3 min: 70–75%\n• 4 min: 75–80% → 5 min: 80–85% → 10 min: 85–95%\n• Monitor on right hand/wrist (preductal)\n• **Avoid hyperoxia** — titrate FiO2 to targets\n\n**Ventilation is the single most important intervention.** Most neonatal bradycardia is caused by inadequate ventilation. [2]","citation":[1,2,3],"next":"nrp-spo2-targets","summary":"PPV is most important intervention — T-piece preferred, C-E grip, PIP 20-30, rate 30-60/min, FiO2 21% (≥35wk) / 21-30% (32-<35wk) / 30-100% (<32wk), confirm chest rise","safetyLevel":"critical"}'::jsonb
WHERE id = 'nrp-ppv' AND tree_id = 'neonatal-resus';

-- Node: nrp-epinephrine (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Epinephrine","body":"EPINEPHRINE — Neonatal Resuscitation [1][2][3]\n\n[Epinephrine](#/drug/epinephrine/neonatal resuscitation)\n\n**IV/IO (preferred):**\n• **0.01–0.03 mg/kg** of 1:10,000 (= 0.1–0.3 mL/kg)\n• Repeat every **3–5 minutes** as needed\n\n**ET (if no IV/IO access):**\n• **0.05–0.1 mg/kg** of 1:10,000 (= 0.5–1 mL/kg)\n• Higher dose needed via ET — absorption is unpredictable\n• Switch to IV/IO route as soon as access established\n\n**IV/IO is ALWAYS preferred over ET.** Establish UVC access as quickly as possible.\n\n**Preparation:**\n• Use **1:10,000 concentration** (0.1 mg/mL)\n• Pre-draw doses in labeled syringes\n• Flush with **3 mL NS** after IV/IO administration, regardless of weight [1]\n\n**Continue CPR between doses.** Do not stop compressions to give epinephrine. [1][2]","citation":[1,2,3],"next":"nrp-uvc","treatment":{"firstLine":{"drug":"Epinephrine","dose":"0.01-0.03 mg/kg (0.1-0.3 mL/kg of 1:10,000)","route":"IV/IO (preferred)","frequency":"Every 3-5 minutes","duration":"Until HR >60 bpm","notes":"Use 1:10,000 concentration (0.1 mg/mL). Flush with 3 mL NS after administration, regardless of weight."},"alternative":{"drug":"Epinephrine","dose":"0.05-0.1 mg/kg (0.5-1 mL/kg of 1:10,000)","route":"ET (endotracheal)","frequency":"Every 3-5 minutes","duration":"Until IV/IO access established","notes":"Higher dose needed via ET due to unpredictable absorption. Switch to IV/IO ASAP."},"monitoring":"Heart rate via cardiac monitor. Goal HR >60 bpm. Continue CPR between doses."},"calculatorLinks":[{"id":"neo-numbers","label":"Neonate Numbers (<3 kg)"},{"id":"peds-dose","label":"Peds Dose Calculator"}],"summary":"Epinephrine 0.01-0.03 mg/kg IV/IO of 1:10,000 q3-5min — IV/IO preferred over ET; flush with NS; continue CPR between doses","safetyLevel":"critical"}'::jsonb
WHERE id = 'nrp-epinephrine' AND tree_id = 'neonatal-resus';

-- Node: nrp-volume (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Volume Resuscitation","body":"VOLUME & GLUCOSE RESUSCITATION [1][2]\n\n**Hypovolemia — clinical signs:**\n• Pallor despite adequate oxygenation\n• Weak pulses\n• Poor response to resuscitation\n• Known maternal hemorrhage or placental abruption\n\n**Normal saline:**\n• **10–20 mL/kg** IV/IO — infuse over 5–10 minutes\n• May repeat if needed\n\n**O-negative pRBCs:**\n• **10–20 mL/kg** — for acute blood loss (abruption, cord avulsion)\n• Uncrossmatched O-negative\n\n**D10W (10% Dextrose):**\n• **2 mL/kg** IV — for hypoglycemia (glucose <40 mg/dL)\n• Neonates have limited glycogen stores — check glucose early\n\n**Naloxone:**\n• **No longer routinely recommended** in neonatal resuscitation\n• PPV is the treatment for respiratory depression, regardless of cause [1]\n\nReassess after volume — if HR improving → continue PPV → post-resuscitation care.","citation":[1,2],"next":"nrp-postresus","treatment":{"firstLine":{"drug":"Normal Saline (0.9% NaCl)","dose":"10-20 mL/kg","route":"IV/IO","frequency":"Once, may repeat","duration":"Infuse over 5-10 minutes","notes":"For suspected hypovolemia (pallor, weak pulses, poor response to resuscitation)."},"alternative":{"drug":"O-negative pRBCs","dose":"10-20 mL/kg","route":"IV/IO","frequency":"Once, may repeat","duration":"Infuse over 5-10 minutes","notes":"For acute blood loss (placental abruption, cord avulsion). Use uncrossmatched O-negative."},"monitoring":"Heart rate, skin perfusion, pulses. Reassess after each bolus. Check glucose early."},"calculatorLinks":[{"id":"weight-dose","label":"Weight-Based Calculator"}],"summary":"NS 10-20 mL/kg IV over 5-10 min for hypovolemia; O-neg pRBCs 10-20 mL/kg for blood loss; D10W 2 mL/kg for hypoglycemia; naloxone NOT recommended"}'::jsonb
WHERE id = 'nrp-volume' AND tree_id = 'neonatal-resus';

