UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"How the Weight Is Chosen","body":"**Priority: measured weight, then length, then age.** A measured weight always wins. Length maps to a zone and uses the zone midpoint. [1][2]\n\n**Age estimate (APLS 2011):** under 12 months, 0.5 x months + 4; 1 to 5 years, 2 x age + 8; 6 to 12 years, 3 x age + 7. Over 12 years the formula is unreliable: use the actual weight. [10][9]\n\n**Obese child:** dose resuscitation drugs by the weight estimated from length or age (ideal weight), not by actual weight.\n\nUnder 3 kg, an age under 1 month, or a gestational age is outside the tape: use [Neonate Numbers](#/node/prn-neonate).","citation":[1,2,9,10],"next":"prn-airway","summary":"Measured weight, then length, then APLS age estimate; obese children by ideal weight"}'::jsonb
